                            t.HasCheckConstraint("ck_usuarios_almacen_requerido", "rol <> 'PERSONAL_ALMACEN' OR almacen_id IS NOT NULL");

                            t.HasCheckConstraint("ck_usuarios_estado", "estado IN ('PENDIENTE_VERIFICACION', 'ACTIVO', 'BLOQUEADO', 'INACTIVO')");

                            t.HasCheckConstraint("ck_usuarios_farmacia_requerida", "rol <> 'PERSONAL_FARMACIA' OR farmacia_id IS NOT NULL");

                            t.HasCheckConstraint("ck_usuarios_municipio_requerido", "rol <> 'SUPERVISOR_MUNICIPAL' OR municipio_id IS NOT NULL");

                            t.HasCheckConstraint("ck_usuarios_rol", "rol IN ('CIUDADANO', 'PERSONAL_FARMACIA', 'PERSONAL_ALMACEN', 'SUPERVISOR_MUNICIPAL', 'ADMINISTRADOR')");
                        });
